CREATE TABLE IF NOT EXISTS public_chat_rooms (
  id text PRIMARY KEY,
  name text NOT NULL,
  description text,
  owner_user_id text NOT NULL,
  model text DEFAULT 'claude-sonnet-4.5',
  system_prompt text,
  agent_id text,
  workflow_id text,
  skills text,
  avatar_url text,
  avatar_gender text DEFAULT 'female',
  bg_color text DEFAULT '#09090b',
  bg_scene text DEFAULT 'none',
  wall_text text,
  wall_logo_url text,
  wall_video_url text,
  wall_layout text,
  fx_state text,
  is_public bigint DEFAULT 1,
  require_auth bigint DEFAULT 0,
  allowed_users text,
  max_message_length bigint DEFAULT 1000,
  rate_limit_seconds bigint DEFAULT 5,
  enable_voice bigint DEFAULT 1,
  enable_avatar bigint DEFAULT 1,
  enable_developer_mode bigint DEFAULT 0,
  embed_enabled bigint DEFAULT 1,
  embed_size text DEFAULT 'medium',
  embed_theme text DEFAULT 'auto',
  message_count bigint DEFAULT 0,
  participant_count bigint DEFAULT 0,
  created_at text DEFAULT (to_char((now() AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS')),
  updated_at text DEFAULT (to_char((now() AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS')),
  FOREIGN KEY (owner_user_id) REFERENCES users (id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config (id) ON DELETE SET NULL,
  FOREIGN KEY (workflow_id) REFERENCES workflows (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_public_rooms_owner ON public_chat_rooms (owner_user_id);

CREATE INDEX IF NOT EXISTS idx_public_rooms_public ON public_chat_rooms (is_public);

CREATE INDEX IF NOT EXISTS idx_public_rooms_created ON public_chat_rooms (created_at DESC);

CREATE TABLE IF NOT EXISTS public_chat_messages (
  id text PRIMARY KEY,
  room_id text NOT NULL,
  user_id text,
  username text NOT NULL,
  role text NOT NULL,
  content text NOT NULL,
  created_at text DEFAULT (to_char((now() AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS')),
  FOREIGN KEY (room_id) REFERENCES public_chat_rooms (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_public_messages_room ON public_chat_messages (room_id);

CREATE INDEX IF NOT EXISTS idx_public_messages_created ON public_chat_messages (created_at DESC);

CREATE TABLE IF NOT EXISTS public_chat_participants (
  id text PRIMARY KEY,
  room_id text NOT NULL,
  user_id text,
  username text NOT NULL,
  joined_at text DEFAULT (to_char((now() AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS')),
  last_seen_at text DEFAULT (to_char((now() AT TIME ZONE 'UTC'), 'YYYY-MM-DD HH24:MI:SS')),
  FOREIGN KEY (room_id) REFERENCES public_chat_rooms (id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_participants_room_user ON public_chat_participants (room_id, user_id, username);

